<?php
require 'config.php'; require_admin(); $page_title='User accounts & approvals';
function pending_path(): string { return __DIR__ . '/data/pending_users.json'; }
function pending_read($fp): array { rewind($fp); $raw=stream_get_contents($fp); $data=json_decode($raw ?: '[]',true); return is_array($data)?$data:[]; }
function pending_write($fp,array $data): void { rewind($fp); ftruncate($fp,0); fwrite($fp,json_encode(array_values($data),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)); fflush($fp); }
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check(); $action=$_POST['action']??'';
 if(in_array($action,['approve','reject'],true)){
  $rid=(string)($_POST['request_id']??''); $fp=@fopen(pending_path(),'c+');
  if(!$fp){flash('Unable to access the pending registration queue.','error');}
  else{flock($fp,LOCK_EX);$pending=pending_read($fp);$found=null;$kept=[];foreach($pending as $item){if(hash_equals((string)($item['request_id']??''),$rid))$found=$item;else $kept[]=$item;}
   if(!$found)flash('Registration request was not found. It may already have been processed.','error');
   elseif($action==='reject'){pending_write($fp,$kept);flash('Registration request rejected.');}
   else{try{$check=$pdo->prepare('SELECT COUNT(*) FROM users WHERE username=? OR email=?');$check->execute([$found['username'],$found['email']]);if((int)$check->fetchColumn()>0)flash('Cannot approve: username or email is already in use. The request remains pending.','error');else{$pdo->prepare('INSERT INTO users(username,full_name,email,password_hash,role) VALUES(?,?,?,?,?)')->execute([$found['username'],$found['full_name'],$found['email'],$found['password_hash'],'User']);pending_write($fp,$kept);flash('Registration approved. The user can now sign in.');}}catch(PDOException $ex){flash('Could not approve this request. Check whether the username or email already exists.','error');}}
   flock($fp,LOCK_UN);fclose($fp);
  }
  header('Location: users.php');exit;
 }
 if($action==='role'){$id=(int)($_POST['user_id']??0);$role=$_POST['role']??'User';if($id===(int)$_SESSION['user_id'])flash('You cannot change your own role here.','error');elseif(!in_array($role,['Admin','User'],true))flash('Invalid role.','error');else{$pdo->prepare('UPDATE users SET role=? WHERE user_id=?')->execute([$role,$id]);flash('Account role updated.');}header('Location: users.php');exit;}
}
$pending=[];$fp=@fopen(pending_path(),'c+');if($fp){flock($fp,LOCK_SH);$pending=pending_read($fp);flock($fp,LOCK_UN);fclose($fp);}
$users=$pdo->query('SELECT user_id,username,full_name,email,role,created_at FROM users ORDER BY created_at DESC')->fetchAll();include 'includes/header.php';?>
<section class="hero"><div><p class="eyebrow">ACCESS CONTROL</p><h1>User accounts & approvals</h1><p class="muted">Review and approve or reject new account registration requests.</p></div></section>
<section class="panel"><div class="panel-head"><h2>Pending sign-up requests</h2><span class="badge <?=count($pending)?'onleave':'active'?>"><?=count($pending)?> pending</span></div><?php if(!$pending): ?><div class="empty">There are no registration requests waiting for approval.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Username</th><th>Email</th><th>Requested</th><th>Decision</th></tr></thead><tbody><?php foreach($pending as $r): ?><tr><td><b><?=e($r['full_name']??'')?></b></td><td><?=e($r['username']??'')?></td><td><?=e($r['email']??'')?></td><td><?=e($r['requested_at']??'')?></td><td><div class="row-actions"><form method="post" onsubmit="return confirm('Approve this registration?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="request_id" value="<?=e($r['request_id']??'')?>"><button class="btn primary">Approve</button></form><form method="post" onsubmit="return confirm('Reject this registration?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reject"><input type="hidden" name="request_id" value="<?=e($r['request_id']??'')?>"><button class="btn danger">Reject</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Existing accounts</h2><span class="muted"><?=count($users)?> account(s)</span></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Created</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><b><?=e($u['full_name'])?></b><small>@<?=e($u['username'])?></small></td><td><?=e($u['email'])?></td><td><?php if((int)$u['user_id']===(int)$_SESSION['user_id']): ?><span class="badge active"><?=e($u['role'])?> (you)</span><?php else: ?><form method="post" class="row-actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><select name="role" aria-label="Role" style="min-width:95px;padding:6px;min-height:34px"><option <?=$u['role']==='User'?'selected':''?>>User</option><option <?=$u['role']==='Admin'?'selected':''?>>Admin</option></select><button class="btn outline">Save</button></form><?php endif; ?></td><td><?=e(substr($u['created_at'],0,10))?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include 'includes/footer.php'; ?>
